import { useState, useEffect, useCallback, useRef } from 'react';
import { chatApi } from '../../services/api';

export const useChat = (initialRoom, config = {}) => {
    const {
        storageKeyPrefix = 'chatMessages',
        canSwitchRooms = true,
        isQuestionMode = false,
        questionMode = 'general'
    } = config;

    const [messages, setMessages] = useState([]);
    const [loading, setLoading] = useState(true);
    const [currentRoom, setCurrentRoom] = useState(initialRoom || 'default');
    const [canSwitch, setCanSwitch] = useState(canSwitchRooms);
    const [currentUserAuthor, setCurrentUserAuthor] = useState('');
    const [isRecording, setIsRecording] = useState(false);
    const [recordingTime, setRecordingTime] = useState(0);
    const [uploading, setUploading] = useState(false);

    const getRoomSlug = useCallback(() => {
        if (isQuestionMode) {
            return `questions-${questionMode}`;
        }
        return currentRoom;
    }, [isQuestionMode, questionMode, currentRoom]);

    const loadMessages = useCallback(async () => {
        try {
            setLoading(true);
            const roomSlug = getRoomSlug();
            const response = await chatApi.getMessagesByRoom(roomSlug, 50);
            setMessages(response.data || []);
        } catch (error) {
            console.error('Failed to load messages:', error);
        } finally {
            setLoading(false);
        }
    }, [getRoomSlug]);

    useEffect(() => {
        loadMessages();
    }, [currentRoom, questionMode, loadMessages]);

    const sendMessage = useCallback(async (content, mediaId = null) => {
        const roomSlug = getRoomSlug();
        try {
            const response = await chatApi.sendMessageToRoom(roomSlug, { content, mediaId });
            setMessages(prev => [...prev, response.data || response]);
            return response.data || response;
        } catch (error) {
            console.error('Failed to send message:', error);
            throw error;
        }
    }, [getRoomSlug]);

    // Остальные функции (editMessage, deleteMessage, recording и т.д.) оставляем как были
    // (они уже работают корректно)

    return {
        messages,
        loading,
        currentRoom,
        canSwitch,
        currentUserAuthor,
        isRecording,
        recordingTime,
        uploading,
        changeRoom: (room) => setCurrentRoom(room),
        sendMessage,
        editMessage: () => {}, // TODO: реализовать позже
        deleteMessage: () => {}, // TODO: реализовать позже
        // ... остальные возвращаемые значения
    };
};

export default useChat;
